function processEvent(e, tokenStore) {
  const t = tokenStore.get(e.userId);
  if (!t) return {forward:false, reason:'no-token'};
  if (Date.now() >= t.expiry) return {forward:false, reason:'expired'};
  if (!verifySignature(e, t.signature)) return {forward:false, reason:'bad-signature'};
